#include <iostream>
#include <string>
#include <algorithm> // 用于std::max函数



// 定义一个函数，用于找出满足条件的最长子字符串的长度
int findLongestSubstringLength(const std::string &s) {
    // 获取输入字符串的长度
    int n = s.length();
    // 初始化最长子字符串长度为0
    int maxLength = 0;

    // 外层循环，从字符串的每一个字符开始检查
    for (int i = 0; i < n; i++) {
        // 初始化'l'、'o'和'x'的计数器
        int countL = 0, countO = 0, countX = 0;

        // 内层循环，从当前字符开始，遍历整个字符串
        for (int j = 0; j < n; j++) {
            // 计算当前字符的索引，处理环形字符串的情况
            int index = (i + j) % n;
            // 获取当前字符
            char ch = s[index];

            // 根据当前字符增加相应字符的计数
            if (ch == 'l') countL++;
            else if (ch == 'o') countO++;
            else if (ch == 'x') countX++;

            // 如果'l'、'o'和'x'出现的次数都是偶数
            if (countL % 2 == 0 && countO % 2 == 0 && countX % 2 == 0) {
                // 更新最长子字符串的长度
                maxLength = std::max(maxLength, j + 1);
            }
        }
    }

    // 返回最长子字符串的长度
    return maxLength;
}

// 主函数
int main() {
    std::string s;
    // 从标准输入读取字符串
    std::cin >> s;

    // 调用findLongestSubstringLength函数计算并返回结果
    int result = findLongestSubstringLength(s);
    // 打印结果
    std::cout << result << std::endl;

    return 0;
}
